<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/page_auth.php';
require_once __DIR__ . '/../config/auth.php';
$pdo = getDatabaseConnection();
imcRequirePageAccess('whatsapp.message.send', null, $pdo);
$csrfToken = htmlspecialchars(generateCsrfToken(), ENT_QUOTES, 'UTF-8');
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="csrf-token" content="<?= $csrfToken ?>"><title>Envoi WhatsApp — IMC-Clarodoro</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:#17212b;font:16px Arial,sans-serif}header{background:#075e54;color:#fff;padding:22px max(18px,calc((100% - 1000px)/2))}header h1{margin:0 0 6px;font-size:26px}header p{margin:0}main{max-width:1000px;margin:24px auto;padding:0 16px}.card{background:#fff;border:1px solid #dce4e8;border-radius:12px;padding:22px;margin-bottom:18px}h2{margin:0 0 16px;color:#075e54;font-size:20px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}label{display:block;font-weight:700;font-size:14px;margin-bottom:6px}input,select,textarea{width:100%;padding:11px;border:1px solid #b8c5cc;border-radius:7px;font:inherit}textarea{min-height:90px}.wide{grid-column:1/-1}button{border:0;border-radius:7px;padding:12px 18px;background:#087f5b;color:#fff;font-weight:700;cursor:pointer}button:disabled{opacity:.55}.hint{color:#52616b;font-size:13px;line-height:1.5}.notice{padding:12px;border-radius:8px;background:#fff6df;color:#664c00;margin-bottom:16px}.result{padding:12px;border-radius:8px;background:#edf7f1;margin-top:14px;white-space:pre-wrap;overflow-wrap:anywhere}.error{background:#fff0f0;color:#8a1717}@media(max-width:650px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.card{padding:16px}}
</style></head><body><header><h1>WhatsApp — envoi manuel</h1><p>IMC-Clarodoro · communication contrôlée avec les parents</p></header><main>
<div class="notice"><strong>Mode sécurisé :</strong> l’envoi reste en simulation tant que <code>WHATSAPP_SEND_ENABLED=true</code> n’est pas configuré côté serveur. Le destinataire vient du consentement enregistré, pas du formulaire.</div>
<section class="card"><h2>1. Vérifier le consentement</h2><div class="grid"><div class="wide"><label for="parent_id">Identifiant UUID du parent</label><input id="parent_id" placeholder="UUID du parent dans PostgreSQL" required></div><div><label for="purpose">Finalité</label><select id="purpose"><option value="ATTENDANCE">Présence / absence</option><option value="RESULTS_AVAILABLE">Résultats disponibles</option><option value="PAYMENT_REMINDER">Rappel de paiement</option><option value="GENERAL">Message général</option></select></div><div style="align-self:end"><button type="button" id="checkConsent">Vérifier le consentement</button></div></div><div id="consentResult" class="result" hidden aria-live="polite"></div><p class="hint">Le consentement doit être actif pour la finalité exacte du message.</p></section>
<section class="card"><h2>2. Composer le message</h2><form id="sendForm" class="grid"><div><label for="template_name">Nom du modèle Meta approuvé</label><input id="template_name" pattern="[a-z0-9_]{1,128}" placeholder="ex. rappel_paiement" required></div><div><label for="language">Langue du modèle</label><select id="language"><option value="fr">Français (fr)</option><option value="fr_FR">Français (fr_FR)</option><option value="en_US">Anglais (en_US)</option><option value="ht">Créole haïtien (ht)</option></select></div><div class="wide"><label for="parameters">Paramètres du modèle (un par ligne)</label><textarea id="parameters" placeholder="Paramètre 1&#10;Paramètre 2"></textarea></div><div class="wide"><button id="sendButton" type="submit">Envoyer / simuler</button><p class="hint">Chaque tentative utilise une clé unique pour empêcher les doublons involontaires.</p></div></form><div id="sendResult" class="result" hidden aria-live="polite"></div></section></main>
<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content,$=id=>document.getElementById(id);
function show(node,text,error=false){node.hidden=false;node.textContent=text;node.classList.toggle('error',error)}
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers:{'Accept':'application/json',...(options.body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{}),...(options.headers||{})}});const d=await r.json().catch(()=>({success:false,error:'Réponse serveur invalide'}));if(!r.ok||d.success===false)throw Error(d.error||('Erreur HTTP '+r.status));return d}
$('checkConsent').addEventListener('click',async()=>{const o=$('consentResult');o.hidden=true;try{const d=await api('/api/whatsapp/consents.php?parent_id='+encodeURIComponent($('parent_id').value.trim()));const c=(d.consents||[]).find(x=>x.purpose===$('purpose').value);show(o,c?'Statut : '+c.status+'\nFinalité : '+c.purpose+'\nTéléphone : '+c.phone_e164+'\nSource : '+(c.consent_source||'non précisée'):'Aucun consentement pour cette finalité.')}catch(e){show(o,e.message,true)}});
$('sendForm').addEventListener('submit',async e=>{e.preventDefault();const b=$('sendButton'),o=$('sendResult');b.disabled=true;o.hidden=true;const parameters=$('parameters').value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);const key=(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2))+'-'+Date.now().toString(36);try{const d=await api('/api/whatsapp/send.php',{method:'POST',body:JSON.stringify({parent_id:$('parent_id').value.trim(),purpose:$('purpose').value,template_name:$('template_name').value.trim(),language:$('language').value,parameters,idempotency_key:key})});show(o,(d.mode==='simulation'?'SIMULATION — aucun message réel envoyé.\n':'Résultat de l’envoi :\n')+(d.message||'Requête traitée')+'\nRéférence journal : '+(d.message_log_id||'non fournie'))}catch(err){show(o,err.message,true)}finally{b.disabled=false}});
</script></body></html>